[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>MedBook — Find and Book Top Doctors Instantly</title>
  <meta name="description" content="Search thousands of doctors, dentists, and specialists. Read verified patient reviews. Book appointments instantly — even same-day.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --navy: #1B1464;
      --navy-light: #2a1f8e;
      --navy-dark: #120e45;
      --yellow: #FFD930;
      --yellow-hover: #f0cc1e;
      --yellow-light: #fff8d6;
      --white: #FFFFFF;
      --gray-50: #f8f9fa;
      --gray-100: #f1f3f5;
      --gray-200: #e9ecef;
      --gray-300: #dee2e6;
      --gray-400: #ced4da;
      --gray-500: #adb5bd;
      --gray-600: #868e96;
      --gray-700: #495057;
      --gray-800: #343a40;
      --gray-900: #212529;
      --teal: #0ca678;
      --teal-light: #e6fcf5;
      --shadow-sm: 0 1px 2px rgba(27,20,100,0.05);
      --shadow-md: 0 4px 12px rgba(27,20,100,0.08);
      --shadow-lg: 0 8px 30px rgba(27,20,100,0.12);
      --shadow-xl: 0 16px 48px rgba(27,20,100,0.15);
      --radius: 12px;
      --radius-lg: 16px;
      --radius-xl: 20px;
      --radius-full: 9999px;
      --transition: 0.2s ease;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      color: var(--gray-800);
      background: var(--white);
      line-height: 1.6;
      font-size: 16px;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
      overflow-x: hidden;
    }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* ===== HEADER ===== */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: rgba(255,255,255,0.95);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid rgba(27,20,100,0.06);
      transition: box-shadow var(--transition);
    }

    .header.scrolled { box-shadow: var(--shadow-md); }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 8px;
      text-decoration: none;
      font-weight: 800;
      font-size: 24px;
      color: var(--navy);
      letter-spacing: -0.5px;
    }

    .logo-icon {
      width: 36px;
      height: 36px;
      background: var(--navy);
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--yellow);
      font-weight: 900;
      font-size: 18px;
    }

    .nav-desktop { display: flex; align-items: center; gap: 8px; }

    .nav-link {
      padding: 8px 16px;
      color: var(--gray-700);
      text-decoration: none;
      font-weight: 500;
      font-size: 15px;
      border-radius: var(--radius);
      transition: all var(--transition);
    }

    .nav-link:hover { color: var(--navy); background: var(--gray-50); }

    .nav-btn-login {
      padding: 8px 20px;
      color: var(--navy);
      text-decoration: none;
      font-weight: 600;
      font-size: 15px;
      border-radius: var(--radius);
      transition: all var(--transition);
    }

    .nav-btn-login:hover { background: var(--gray-50); }

    .nav-btn-signup {
      padding: 8px 20px;
      background: var(--navy);
      color: var(--white);
      text-decoration: none;
      font-weight: 600;
      font-size: 15px;
      border-radius: var(--radius);
      border: none;
      cursor: pointer;
      transition: all var(--transition);
    }

    .nav-btn-signup:hover { background: var(--navy-light); transform: translateY(-1px); }

    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      background: none;
      border: none;
      cursor: pointer;
      padding: 8px;
      border-radius: 8px;
      transition: background var(--transition);
    }

    .hamburger:hover { background: var(--gray-100); }

    .hamburger span {
      display: block;
      width: 22px;
      height: 2px;
      background: var(--navy);
      border-radius: 2px;
      transition: all 0.3s ease;
    }

    .hamburger.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
    .hamburger.active span:nth-child(2) { opacity: 0; }
    .hamburger.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

    /* Mobile drawer */
    .mobile-drawer {
      position: fixed;
      top: 72px;
      right: -100%;
      width: 300px;
      height: calc(100vh - 72px);
      background: var(--white);
      box-shadow: -8px 0 30px rgba(27,20,100,0.15);
      z-index: 999;
      transition: right 0.35s cubic-bezier(0.4, 0, 0.2, 1);
      padding: 24px;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .mobile-drawer.open { right: 0; }

    .mobile-overlay {
      position: fixed;
      top: 72px;
      left: 0;
      right: 0;
      bottom: 0;
      background: rgba(27,20,100,0.3);
      z-index: 998;
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.3s ease;
    }

    .mobile-overlay.open { opacity: 1; pointer-events: auto; }

    .mobile-drawer a {
      display: block;
      padding: 14px 16px;
      color: var(--gray-800);
      text-decoration: none;
      font-weight: 500;
      font-size: 16px;
      border-radius: var(--radius);
      transition: all var(--transition);
    }

    .mobile-drawer a:hover { background: var(--gray-50); color: var(--navy); }

    .mobile-drawer .mobile-signup {
      margin-top: 8px;
      background: var(--navy);
      color: var(--white);
      font-weight: 600;
      text-align: center;
    }

    .mobile-drawer .mobile-signup:hover { background: var(--navy-light); }

    /* ===== HERO ===== */
    .hero {
      padding: 140px 0 80px;
      background: linear-gradient(180deg, #f0eeff 0%, var(--white) 100%);
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -200px;
      right: -200px;
      width: 500px;
      height: 500px;
      background: radial-gradient(circle, rgba(255,217,48,0.15) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero::after {
      content: '';
      position: absolute;
      bottom: -100px;
      left: -150px;
      width: 400px;
      height: 400px;
      background: radial-gradient(circle, rgba(27,20,100,0.06) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero-content {
      text-align: center;
      max-width: 720px;
      margin: 0 auto;
      position: relative;
      z-index: 1;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 6px 16px;
      background: var(--yellow-light);
      color: var(--navy);
      font-weight: 600;
      font-size: 13px;
      border-radius: var(--radius-full);
      margin-bottom: 24px;
      letter-spacing: 0.02em;
    }

    .hero h1 {
      font-size: clamp(36px, 5vw, 56px);
      font-weight: 900;
      color: var(--navy);
      line-height: 1.1;
      letter-spacing: -1.5px;
      margin-bottom: 20px;
    }

    .hero p {
      font-size: clamp(16px, 2vw, 19px);
      color: var(--gray-600);
      line-height: 1.7;
      max-width: 580px;
      margin: 0 auto 40px;
    }

    /* ===== SEARCH BAR ===== */
    .search-wrapper {
      max-width: 800px;
      margin: 0 auto;
      position: relative;
      z-index: 10;
    }

    .search-bar {
      display: flex;
      align-items: stretch;
      background: var(--white);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-xl);
      border: 2px solid transparent;
      transition: border-color var(--transition), box-shadow var(--transition);
      overflow: visible;
      position: relative;
    }

    .search-bar:focus-within {
      border-color: var(--navy);
      box-shadow: var(--shadow-xl), 0 0 0 4px rgba(27,20,100,0.08);
    }

    .search-field {
      flex: 1;
      position: relative;
      min-width: 0;
    }

    .search-field + .search-field { border-left: 1px solid var(--gray-200); }

    .search-field label {
      position: absolute;
      top: 12px;
      left: 48px;
      font-size: 11px;
      font-weight: 700;
      color: var(--navy);
      text-transform: uppercase;
      letter-spacing: 0.06em;
    }

    .search-field .field-icon {
      position: absolute;
      left: 16px;
      top: 50%;
      transform: translateY(-50%);
      width: 20px;
      height: 20px;
      color: var(--gray-400);
    }

    .search-field input,
    .search-field select {
      width: 100%;
      height: 72px;
      padding: 30px 16px 10px 48px;
      border: none;
      background: transparent;
      font-size: 15px;
      font-family: inherit;
      color: var(--gray-800);
      outline: none;
    }

    .search-field input::placeholder,
    .search-field select { color: var(--gray-400); }

    .search-field select {
      appearance: none;
      cursor: pointer;
      color: var(--gray-400);
    }

    .search-field select:valid { color: var(--gray-800); }

    .search-btn {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 0 28px;
      background: var(--yellow);
      color: var(--navy);
      border: none;
      font-weight: 700;
      font-size: 16px;
      font-family: inherit;
      cursor: pointer;
      border-radius: 0 14px 14px 0;
      transition: all var(--transition);
      white-space: nowrap;
    }

    .search-btn:hover { background: var(--yellow-hover); }
    .search-btn:active { transform: scale(0.98); }

    .search-btn svg { width: 20px; height: 20px; }

    /* Autocomplete dropdown */
    .autocomplete-dropdown {
      position: absolute;
      top: calc(100% + 4px);
      left: 0;
      right: 0;
      background: var(--white);
      border-radius: var(--radius);
      box-shadow: var(--shadow-lg);
      border: 1px solid var(--gray-200);
      display: none;
      z-index: 20;
      overflow: hidden;
      max-height: 280px;
      overflow-y: auto;
    }

    .autocomplete-dropdown.show { display: block; animation: fadeDown 0.15s ease; }

    @keyframes fadeDown {
      from { opacity: 0; transform: translateY(-4px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .autocomplete-item {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 12px 16px;
      cursor: pointer;
      transition: background var(--transition);
      font-size: 14px;
    }

    .autocomplete-item:hover { background: var(--gray-50); }

    .autocomplete-item .item-icon {
      width: 32px;
      height: 32px;
      border-radius: 8px;
      background: var(--gray-100);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--navy);
      font-size: 14px;
      flex-shrink: 0;
    }

    .autocomplete-item .item-label { font-weight: 500; color: var(--gray-800); }
    .autocomplete-item .item-type { font-size: 12px; color: var(--gray-500); margin-top: 1px; }

    .search-hint {
      text-align: center;
      margin-top: 16px;
      font-size: 13px;
      color: var(--gray-500);
    }

    .search-hint strong { color: var(--gray-700); font-weight: 600; }

    /* ===== SPECIALTIES ===== */
    .specialties {
      padding: 80px 0;
      background: var(--white);
    }

    .section-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .section-label {
      display: inline-block;
      font-size: 13px;
      font-weight: 700;
      color: var(--navy);
      text-transform: uppercase;
      letter-spacing: 0.08em;
      margin-bottom: 12px;
      background: rgba(27,20,100,0.06);
      padding: 4px 14px;
      border-radius: var(--radius-full);
    }

    .section-title {
      font-size: clamp(28px, 3.5vw, 40px);
      font-weight: 800;
      color: var(--navy);
      letter-spacing: -0.8px;
      line-height: 1.2;
      margin-bottom: 12px;
    }

    .section-subtitle {
      font-size: 17px;
      color: var(--gray-600);
      max-width: 520px;
      margin: 0 auto;
    }

    .specialties-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
    }

    .specialty-card {
      display: flex;
      align-items: center;
      gap: 16px;
      padding: 24px;
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      cursor: pointer;
      transition: all var(--transition);
      text-decoration: none;
      color: inherit;
    }

    .specialty-card:hover {
      border-color: var(--navy);
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .specialty-icon {
      width: 56px;
      height: 56px;
      border-radius: var(--radius);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 26px;
      flex-shrink: 0;
    }

    .specialty-card:nth-child(1) .specialty-icon { background: #e8f4fd; }
    .specialty-card:nth-child(2) .specialty-icon { background: #e6fcf5; }
    .specialty-card:nth-child(3) .specialty-icon { background: #fff3e6; }
    .specialty-card:nth-child(4) .specialty-icon { background: #f3e8ff; }
    .specialty-card:nth-child(5) .specialty-icon { background: #e8f0fe; }
    .specialty-card:nth-child(6) .specialty-icon { background: #fce8e8; }

    .specialty-name {
      font-weight: 700;
      font-size: 16px;
      color: var(--navy);
      margin-bottom: 4px;
    }

    .specialty-desc {
      font-size: 13px;
      color: var(--gray-500);
      line-height: 1.4;
    }

    /* ===== HOW IT WORKS ===== */
    .how-it-works {
      padding: 80px 0;
      background: var(--gray-50);
    }

    .steps-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 32px;
      position: relative;
    }

    .steps-grid::before {
      content: '';
      position: absolute;
      top: 40px;
      left: calc(16.67% + 24px);
      right: calc(16.67% + 24px);
      height: 2px;
      background: linear-gradient(90deg, var(--yellow) 0%, var(--navy) 100%);
      opacity: 0.3;
    }

    .step-card { text-align: center; position: relative; z-index: 1; }

    .step-number {
      width: 80px;
      height: 80px;
      border-radius: 50%;
      background: var(--white);
      border: 3px solid var(--yellow);
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 24px;
      font-weight: 800;
      font-size: 28px;
      color: var(--navy);
      box-shadow: var(--shadow-md);
      transition: all 0.3s ease;
    }

    .step-card:hover .step-number {
      background: var(--yellow);
      transform: scale(1.08);
    }

    .step-title {
      font-size: 20px;
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 12px;
    }

    .step-text {
      font-size: 15px;
      color: var(--gray-600);
      line-height: 1.6;
      max-width: 300px;
      margin: 0 auto;
    }

    /* ===== STATS ===== */
    .stats {
      padding: 60px 0;
      background: var(--navy);
      position: relative;
      overflow: hidden;
    }

    .stats::before {
      content: '';
      position: absolute;
      top: -50%;
      right: -10%;
      width: 400px;
      height: 400px;
      background: radial-gradient(circle, rgba(255,217,48,0.12) 0%, transparent 70%);
      pointer-events: none;
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 32px;
      text-align: center;
      position: relative;
      z-index: 1;
    }

    .stat-item {}

    .stat-value {
      font-size: clamp(32px, 4vw, 44px);
      font-weight: 900;
      color: var(--yellow);
      letter-spacing: -1px;
      line-height: 1;
      margin-bottom: 8px;
    }

    .stat-label {
      font-size: 15px;
      color: rgba(255,255,255,0.75);
      font-weight: 500;
    }

    /* ===== TESTIMONIALS ===== */
    .testimonials {
      padding: 80px 0;
      background: var(--white);
    }

    .testimonials-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .testimonial-card {
      padding: 32px;
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      transition: all var(--transition);
    }

    .testimonial-card:hover {
      box-shadow: var(--shadow-lg);
      transform: translateY(-3px);
    }

    .testimonial-stars {
      display: flex;
      gap: 2px;
      margin-bottom: 16px;
    }

    .testimonial-stars svg { width: 18px; height: 18px; color: var(--yellow); fill: var(--yellow); }

    .testimonial-text {
      font-size: 15px;
      color: var(--gray-700);
      line-height: 1.7;
      margin-bottom: 20px;
      font-style: italic;
    }

    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .testimonial-avatar {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      background: var(--navy);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--yellow);
      font-weight: 700;
      font-size: 16px;
    }

    .testimonial-name {
      font-weight: 700;
      font-size: 15px;
      color: var(--navy);
    }

    .testimonial-location {
      font-size: 13px;
      color: var(--gray-500);
    }

    /* ===== MOBILE APP PROMO ===== */
    .app-promo {
      padding: 80px 0;
      background: var(--gray-50);
    }

    .app-promo-inner {
      display: flex;
      align-items: center;
      gap: 64px;
    }

    .app-promo-content { flex: 1; }

    .app-promo-content h2 {
      font-size: clamp(28px, 3.5vw, 40px);
      font-weight: 800;
      color: var(--navy);
      letter-spacing: -0.8px;
      margin-bottom: 16px;
    }

    .app-promo-content > p {
      font-size: 17px;
      color: var(--gray-600);
      margin-bottom: 32px;
      line-height: 1.7;
      max-width: 460px;
    }

    .app-features {
      list-style: none;
      margin-bottom: 36px;
      display: grid;
      gap: 14px;
    }

    .app-features li {
      display: flex;
      align-items: center;
      gap: 12px;
      font-size: 15px;
      color: var(--gray-700);
      font-weight: 500;
    }

    .app-features li svg {
      width: 22px;
      height: 22px;
      color: var(--teal);
      flex-shrink: 0;
    }

    .app-buttons {
      display: flex;
      gap: 12px;
      flex-wrap: wrap;
    }

    .app-btn {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      padding: 12px 24px;
      background: var(--navy);
      color: var(--white);
      border-radius: var(--radius);
      text-decoration: none;
      font-weight: 600;
      font-size: 14px;
      transition: all var(--transition);
    }

    .app-btn:hover { background: var(--navy-light); transform: translateY(-1px); }
    .app-btn svg { width: 22px; height: 22px; }

    .app-promo-visual {
      flex: 0 0 320px;
      position: relative;
    }

    .phone-mockup {
      width: 280px;
      height: 560px;
      background: var(--navy);
      border-radius: 36px;
      padding: 12px;
      box-shadow: var(--shadow-xl);
      margin: 0 auto;
      position: relative;
    }

    .phone-screen {
      width: 100%;
      height: 100%;
      background: var(--white);
      border-radius: 26px;
      overflow: hidden;
      display: flex;
      flex-direction: column;
    }

    .phone-status-bar {
      height: 44px;
      background: var(--navy);
      display: flex;
      align-items: center;
      justify-content: center;
      padding-top: 10px;
    }

    .phone-notch {
      width: 120px;
      height: 28px;
      background: var(--navy-dark);
      border-radius: 0 0 16px 16px;
    }

    .phone-content {
      flex: 1;
      padding: 20px 16px;
      display: flex;
      flex-direction: column;
      gap: 16px;
    }

    .phone-greeting {
      font-size: 11px;
      color: var(--gray-500);
    }

    .phone-title {
      font-size: 18px;
      font-weight: 800;
      color: var(--navy);
      line-height: 1.2;
    }

    .phone-search-bar {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 10px 12px;
      background: var(--gray-100);
      border-radius: 10px;
      font-size: 12px;
      color: var(--gray-400);
    }

    .phone-card {
      background: var(--gray-50);
      border-radius: 12px;
      padding: 12px;
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .phone-card-avatar {
      width: 36px;
      height: 36px;
      border-radius: 10px;
      background: var(--navy);
      display: flex;
